import { Config } from './packages/core/src/config/config.js';
import { debugLogger } from './packages/core/src/utils/debugLogger.js';

async function verifyStage2() {
  console.log('--- Starting Stage 2 Manual Verification ---');

  const config = new Config({
    sessionId: 'stage2-verify-session',
    targetDir: process.cwd(),
    debugMode: true,
    model: 'gemini-1.5-flash',
    cwd: process.cwd(),
  });

  try {
    await config.initialize();

    const teamRegistry = config.getTeamRegistry();
    const teams = teamRegistry.getAllTeams();

    console.log(`Found ${teams.length} teams.`);

    for (const team of teams) {
      console.log(`- Team: ${team.name} (${team.displayName})`);
      console.log(`  Description: ${team.description}`);
    }

    const sharedTeam = teamRegistry.getTeam('shared-team');
    if (sharedTeam?.displayName === 'Project Overridden Team') {
      console.log('\n✅ Precedence Check: Project team correctly overrode global team.');
    } else {
      console.error('\n❌ Precedence Check Failed: Expected project team override.');
    }

    const projectOnly = teamRegistry.getTeam('project-only-team');
    if (projectOnly) {
      console.log('✅ Discovery Check: Project-only team found.');
    } else {
      console.error('❌ Discovery Check Failed: Project-only team not found.');
    }

    if (teams.length >= 2) {
      console.log('\n✅ Stage 2 Verification Successful.');
    } else {
      console.error('\n❌ Stage 2 Verification Failed: Missing teams.');
      process.exit(1);
    }
  } catch (error) {
    console.error('\n❌ Verification Error:', error);
    process.exit(1);
  }
}

verifyStage2();

