        -->
    </key_knowledge>

    <artifact_trail>
        <!-- Evolution of critical files and symbols. What was changed and WHY. Use this to track all significant code modifications and design decisions. -->
        <!-- Example:
         - \`src/auth.ts\`: Refactored 'login' to 'signIn' to match API v2 specs.
