import { Config } from './packages/core/src/config/config.js';
import { PromptProvider } from './packages/core/src/prompts/promptProvider.js';
import { type AgentLoopContext } from './packages/core/src/config/agent-loop-context.js';
import { ToolRegistry } from './packages/core/src/tools/tool-registry.js';
import { MessageBus } from './packages/core/src/confirmation-bus/message-bus.js';

async function verifyOrchestration() {
  console.log('--- Starting Orchestration Manual Verification ---');

  const config = new Config({
    sessionId: 'orch-verify-session',
    targetDir: process.cwd(),
    debugMode: true,
    model: 'gemini-3.1-pro-preview',
    cwd: process.cwd(),
  });

  try {
    await config.initialize();

    config.setActiveTeam('orchestration-team');
    console.log(`Active team set to: ${config.getActiveTeam()?.displayName}`);

    const promptProvider = new PromptProvider();

    // Trigger a full reload to ensure tools are re-registered with team awareness
    await config.getAgentRegistry().reload();

    const context: AgentLoopContext = {
      config,
      toolRegistry: config.getToolRegistry(),
    };

    const prompt = promptProvider.getCoreSystemPrompt(context);

    if (prompt.includes('SPECIAL ORCHESTRATION INSTRUCTIONS')) {
      console.log('✅ Prompt Injection: Team instructions found in system prompt.');
    } else {
      console.error('❌ Prompt Injection Failed: Team instructions NOT found.');
    }

    const specialAgentTool = config.getToolRegistry().getTool('special-agent');
    if (specialAgentTool && specialAgentTool.description.includes('(Team Agent: Orchestration Team)')) {
      console.log('✅ Tool Enhancement: special-agent description enhanced with team info.');
    } else {
      console.error('❌ Tool Enhancement Failed: special-agent description NOT enhanced.');
      if (specialAgentTool) {
        console.log(`Actual description: ${specialAgentTool.description}`);
      }
    }

    if (prompt.includes('SPECIAL ORCHESTRATION INSTRUCTIONS') && specialAgentTool?.description.includes('(Team Agent: Orchestration Team)')) {
      console.log('\n✅ Orchestration Verification Successful.');
    } else {
      console.error('\n❌ Orchestration Verification Failed.');
      process.exit(1);
    }
  } catch (error) {
    console.error('\n❌ Verification Error:', error);
    process.exit(1);
  }
}

verifyOrchestration();

