  useEffect,
  useRef,
  useLayoutEffect,
} from 'react';
import {
  type DOMElement,
  ResizeObserver,
  useApp,
  useStdout,
  useStdin,
  type AppProps,
} from 'ink';
import { App } from './App.js';
