        addInput(submittedValue);
        return;
      }

      const isMcpOrConfigReady = isConfigInitialized && isMcpReady;
      if ((isSlash && isConfigInitialized) || (isIdle && isMcpOrConfigReady)) {
        if (!isSlash) {
