export function markdownToAgentDefinition(
  markdown: FrontmatterAgentDefinition,
  metadata?: { hash?: string; filePath?: string },
): AgentDefinition {
  const inputConfig = {
    inputSchema: {
      type: 'object',
      properties: {
        query: {
          type: 'string',
          description: 'The task for the agent.',
        },
      },
      // query is not required because it defaults to "Get Started!" if not provided
      required: [],
    },
  };

  switch (markdown.kind) {
    case 'remote': {
      const base: RemoteAgentDefinition = {
        kind: 'remote',
        name: markdown.name,
        description: markdown.description || '',
        displayName: markdown.display_name,
        auth: markdown.auth
          ? convertFrontmatterAuthToConfig(markdown.auth)
          : undefined,
        inputConfig,
        metadata,
      };

      if (
        'agent_card_json' in markdown &&
        markdown.agent_card_json !== undefined
      ) {
        base.agentCardJson = markdown.agent_card_json;
        return base;
      }
      if (
        'agent_card_url' in markdown &&
        markdown.agent_card_url !== undefined
      ) {
        base.agentCardUrl = markdown.agent_card_url;
        return base;
      }

      throw new AgentLoadError(
        metadata?.filePath || 'unknown',
        'Unexpected state: neither agent_card_json nor agent_card_url present on remote agent',
      );
    }

    case 'external': {
      const mcpServers: Record<string, MCPServerConfig> = {};
      if (markdown.mcp_servers) {
        for (const [name, config] of Object.entries(markdown.mcp_servers)) {
          mcpServers[name] = new MCPServerConfig(
            config.command,
            config.args,
            config.env,
            config.cwd,
            config.url,
            config.http_url,
            config.headers,
            config.tcp,
            config.type,
            config.timeout,
            config.trust,
            config.description,
            config.include_tools,
            config.exclude_tools,
          );
        }
      }

      return {
        kind: 'external',
        name: markdown.name,
        provider: markdown.provider,
        description: markdown.description,
        displayName: markdown.display_name,
        providerConfig: markdown.provider_config,
        toolConfig: markdown.tools
          ? {
              tools: markdown.tools,
            }
          : undefined,
        mcpServers: Object.keys(mcpServers).length > 0 ? mcpServers : undefined,
        inputConfig,
        metadata,
      };
    }

    case 'local': {
      // If a model is specified, use it. Otherwise, inherit
      const modelName = markdown.model || 'inherit';

      const mcpServers: Record<string, MCPServerConfig> = {};
      if (markdown.mcp_servers) {
        for (const [name, config] of Object.entries(markdown.mcp_servers)) {
          mcpServers[name] = new MCPServerConfig(
            config.command,
            config.args,
            config.env,
            config.cwd,
            config.url,
            config.http_url,
            config.headers,
            config.tcp,
            config.type,
            config.timeout,
            config.trust,
            config.description,
            config.include_tools,
            config.exclude_tools,
          );
        }
      }

      return {
        kind: 'local',
        name: markdown.name,
        description: markdown.description,
        displayName: markdown.display_name,
        promptConfig: {
          systemPrompt: markdown.system_prompt,
          query: '${query}',
        },
        modelConfig: {
          model: modelName,
          generateContentConfig: {
            temperature: markdown.temperature ?? 1,
            topP: 0.95,
          },
        },
        runConfig: {
          maxTurns: markdown.max_turns ?? DEFAULT_MAX_TURNS,
          maxTimeMinutes: markdown.timeout_mins ?? DEFAULT_MAX_TIME_MINUTES,
        },
        toolConfig: markdown.tools
          ? {
              tools: markdown.tools,
            }
          : undefined,
        mcpServers: Object.keys(mcpServers).length > 0 ? mcpServers : undefined,
        inputConfig,
        metadata,
      };
    }

    default: {
      const exhaustive: never = markdown;
      throw new Error(
        `Unsupported agent kind: ${String((exhaustive as any).kind)}`,
      );
    }
  }
}

