        }
      }

      return {
        kind: 'external',
        name: markdown.name,
        provider: markdown.provider,
        description: markdown.description,
        displayName: markdown.display_name,
        providerConfig: markdown.provider_config,
        toolConfig: markdown.tools
          ? {
              tools: markdown.tools,
            }
          : undefined,
        mcpServers: Object.keys(mcpServers).length > 0 ? mcpServers : undefined,
        inputConfig,
        metadata,
      };
    }

    case 'local': {
      // If a model is specified, use it. Otherwise, inherit
      const modelName = markdown.model || 'inherit';

      const mcpServers: Record<string, MCPServerConfig> = {};
      if (markdown.mcp_servers) {
        for (const [name, config] of Object.entries(markdown.mcp_servers)) {
          mcpServers[name] = new MCPServerConfig(
            config.command,
            config.args,
            config.env,
            config.cwd,
            config.url,
            config.http_url,
            config.headers,
            config.tcp,
            config.type,
            config.timeout,
            config.trust,
            config.description,
            config.include_tools,
            config.exclude_tools,
          );
        }
      }

      return {
        kind: 'local',
        name: markdown.name,
        description: markdown.description,
        displayName: markdown.display_name,
        promptConfig: {
          systemPrompt: markdown.system_prompt,
          query: '${query}',
        },
        modelConfig: {
          model: modelName,
