  const input = rawInput as Partial<FrontmatterLocalAgentDefinition> &
    Partial<FrontmatterRemoteAgentDefinition>;

  if (input.kind === 'local') return 'local';
  if (input.kind === 'remote') return 'remote';

  const hasLocalKeys =
    'tools' in input ||
    'mcp_servers' in input ||
