export function DescriptiveRadioButtonSelect<T>({
  items,
  initialIndex = 0,
  onSelect,
  onHighlight,
  isFocused = true,
  showNumbers = false,
  showScrollArrows = false,
  maxItemsToShow = 10,
}: DescriptiveRadioButtonSelectProps<T>): React.JSX.Element {
  return (
    <BaseSelectionList<T, DescriptiveRadioSelectItem<T>>
      items={items}
      initialIndex={initialIndex}
      onSelect={onSelect}
      onHighlight={onHighlight}
      isFocused={isFocused}
      showNumbers={showNumbers}
      showScrollArrows={showScrollArrows}
      maxItemsToShow={maxItemsToShow}
      renderItem={(item, { titleColor }) => (
        <Box flexDirection="column" key={item.key}>
          <Box flexDirection="row">
            <Text color={titleColor}>{item.title}</Text>
            {item.titleSuffix && <Box marginLeft={1}>{item.titleSuffix}</Box>}
          </Box>
          {item.description && (
            <Text color={theme.text.secondary}>{item.description}</Text>
          )}
        </Box>
      )}
    />
  );
}

