  elapsedTime,
  currentWittyPhrase,
  activeHooks,
  showLoadingIndicator,
  errorVerbosity,
  onResize,
}) => {
  const observerRef = useRef<ResizeObserver | null>(null);

  const onRefChange = useCallback(
    (node: DOMElement | null) => {
      if (observerRef.current) {
