/**
 * @license
 * Copyright 2026 Google LLC
 * SPDX-License-Identifier: Apache-2.0
 */

import type React from 'react';
import { useCallback, useMemo, useState } from 'react';
import { Box, Text, useInput } from 'ink';
import {
  type TeamDefinition,
  type AgentDefinition,
} from '@google/gemini-cli-core';
import { theme } from '../semantic-colors.js';
import { DescriptiveRadioButtonSelect } from './shared/DescriptiveRadioButtonSelect.js';

interface TeamSelectionDialogProps {
  teams: TeamDefinition[];
  onSelect: (teamName: string | undefined) => void;
}

const PROVIDER_COLORS = {
  'claude-code': '#D8B4FE', // Anthropic Purple (Lightish)
  codex: '#6EE7B7', // OpenAI Green
  gemini: '#60A5FA', // Google Blue
};

const ProviderTag: React.FC<{ provider: string }> = ({ provider }) => {
  const label =
    provider === 'claude-code' ? 'C' : provider === 'codex' ? 'X' : 'G';
  const color =
    PROVIDER_COLORS[provider as keyof typeof PROVIDER_COLORS] ||
    theme.text.secondary;

  return (
    <Box borderStyle="round" borderColor={color} paddingX={0.5}>
      <Text color={color} bold>
        {label}
      </Text>
    </Box>
  );
};

const MultiModelBadge: React.FC = () => (
  <Box
    borderStyle="single"
    borderColor={theme.ui.focus}
    paddingX={0.5}
    marginLeft={1}
  >
    <Text color={theme.ui.focus} bold>
      MULTI-MODEL
    </Text>
  </Box>
);

function getProviderTags(agents: AgentDefinition[]): React.ReactNode {
  const providers = new Set<string>();
  for (const agent of agents) {
    if (agent.kind === 'external') {
      providers.add(agent.provider);
    } else {
      providers.add('gemini');
    }
  }

  const sortedProviders = Array.from(providers).sort();
  const isMulti = providers.size > 1;

  return (
    <Box flexDirection="row" alignItems="center">
      {sortedProviders.map((p) => (
        <Box key={p} marginLeft={0.5}>
          <ProviderTag provider={p} />
        </Box>
      ))}
      {isMulti && <MultiModelBadge />}
    </Box>
  );
}

export function TeamSelectionDialog({
  teams: discoveredTeams,
  onSelect,
}: TeamSelectionDialogProps): React.JSX.Element {
  const [view, setView] = useState<'select' | 'marketplace' | 'create'>(
    'select',
  );

  useInput(() => {
    if (view !== 'select') {
      setView('select');
    }
