      description: 'Define your own agent team and orchestration instructions',
      key: 'create',
      titleSuffix: undefined,
    });

    return list;
  }, [discoveredTeams]);

  const handleSelect = useCallback(
    (value: string) => {
      if (value === 'none') {
        onSelect(undefined);
      } else if (value === 'marketplace') {
        setView('marketplace');
      } else if (value === 'create') {
        setView('create');
      } else {
        onSelect(value);
      }
    },
    [onSelect],
  );

  if (view === 'marketplace') {
    return (
