        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        {
          kind: 'external',
          name: 'claude-coder',
          provider: 'claude-code',
          description: 'Claude Coder',
          inputConfig: { type: 'object', properties: {}, required: [] },
        } as unknown as AgentDefinition,
        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
