          <Text color={theme.text.primary}>
            3. (Optional) Add specialized agents to an agents/ sub-directory.
          </Text>

          <Box
            marginTop={1}
            padding={1}
            borderStyle="single"
            borderColor={theme.ui.focus}
          >
            <Text color={theme.ui.focus}>
              Tip: You can now specify external agents directly in TEAM.md!
            </Text>
          </Box>

          <Box marginTop={1}>
            <Text color={theme.text.accent}>
              Press any key to go back to selection...
            </Text>
          </Box>
        </Box>
      </Box>
    );
  }

  return (
    <Box
      borderStyle="round"
      borderColor={theme.border.default}
      flexDirection="column"
      padding={1}
      width="100%"
    >
      <Text bold color={theme.text.primary}>
        Select an Agent Team
      </Text>
      <Text color={theme.text.secondary}>
        Choose a specialized team to orchestrate your tasks.
      </Text>

      <Box marginTop={1}>
        <DescriptiveRadioButtonSelect
          items={options}
          onSelect={handleSelect}
          showNumbers={true}
          maxItemsToShow={10}
        />
      </Box>

      <Box marginTop={1}>
        <Text color={theme.text.secondary}>
          (Use arrow keys to navigate, Enter to select)
        </Text>
      </Box>
    </Box>
  );
}

