  provider?: string;
  description?: string;
  sourcePath?: string;
}

export interface ScaffoldTeamOptions {
  name: string;
  displayName: string;
  description: string;
  instructions: string;
  agents: ScaffoldTeamAgent[];
  targetDir: string;
}

/**
 * Scaffolds a new Agent Team directory and its associated files.
 *
 * @param options Configuration for the team to be created.
 * @returns The absolute path to the created team directory.
 */
export async function scaffoldTeam(
  options: ScaffoldTeamOptions,
): Promise<string> {
  const teamSlug = options.name.toLowerCase().replace(/[^a-z0-9-_]/g, '-');
  const teamDirPath = path.join(options.targetDir, teamSlug);

  try {
    // 1. Create team directory
    await fs.mkdir(teamDirPath, { recursive: true });

    // 2. Separate agents into inline (external) and standalone (local)
    const inlineAgents = options.agents
      .filter((a) => a.kind === 'external')
      .map((a) => ({
        kind: 'external',
        name: a.name,
        provider: a.provider,
        description: a.description || \`Expert \${a.name} agent.\`,
      }));

    const localAgents = options.agents.filter((a) => a.kind === 'local');

    // 3. Generate TEAM.md content
    const frontmatter = {
      name: teamSlug,
      display_name: options.displayName,
      description: options.description,
      agents: inlineAgents.length > 0 ? inlineAgents : undefined,
    };

    const teamMdContent = \`---
\${dump(frontmatter).trim()}
---

\${options.instructions.trim()}
\`;

    await fs.writeFile(
      path.join(teamDirPath, 'TEAM.md'),
      teamMdContent,
      'utf-8',
    );

    // 4. Create agents/ sub-directory if there are local agents
    if (localAgents.length > 0) {
      const agentsDirPath = path.join(teamDirPath, 'agents');
      await fs.mkdir(agentsDirPath, { recursive: true });

      for (const agent of localAgents) {
        if (agent.sourcePath) {
          const destPath = path.join(
            agentsDirPath,
            path.basename(agent.sourcePath),
          );
          await fs.copyFile(agent.sourcePath, destPath);
        }
      }
    }

    return teamDirPath;
  } catch (error) {
    throw new Error(\`Failed to scaffold team "\${options.name}": \${getErrorMessage(error)}\`);
  }
}
