          await config.refreshAuth(authType);
          setAuthState(AuthState.Authenticated);
          logBillingEvent(
            config,
            new ApiKeyUpdatedEvent(previousAuthType, authType),
          );
        } catch (e) {
          if (e instanceof ChangeAuthRequestedError) {
            return;
