        targetDir: config.storage.getProjectTeamsDir(),
      });
      await config.getTeamRegistry().reload();
      setStep('success');
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setIsSubmitting(false);
    }
  };

  // Identity Step Buffers
  const nameBuffer = useTextBuffer({
    initialText: teamName,
    viewport: { width: 40, height: 1 },
    onChange: setTeamName,
    singleLine: true,
  });
  const displayNameBuffer = useTextBuffer({
    initialText: displayName,
    viewport: { width: 40, height: 1 },
    onChange: setDisplayName,
    singleLine: true,
  });
  const descBuffer = useTextBuffer({
    initialText: description,
    viewport: { width: 80, height: 1 },
    onChange: setDescription,
    singleLine: true,
  });

  // Objective Step Buffer
  const instructionsBuffer = useTextBuffer({
    initialText: instructions,
    viewport: { width: 80, height: 5 },
    onChange: setInstructions,
  });

  const [activeIdentityField, setActiveIdentityField] = useState<0 | 1 | 2>(0);

  const handleIdentityKeyPress = useCallback(
    (key: Key) => {
      if (keyMatchers[Command.DIALOG_NAVIGATION_DOWN](key)) {
        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        setActiveIdentityField(((activeIdentityField + 1) % 3) as any);
        return true;
      }
      if (keyMatchers[Command.DIALOG_NAVIGATION_UP](key)) {
        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        setActiveIdentityField(((activeIdentityField + 2) % 3) as any);
        return true;
      }
      if (keyMatchers[Command.ESCAPE](key)) {
        onCancel();
        return true;
      }
      return false;
    },
    [activeIdentityField, keyMatchers, onCancel],
  );

  useKeypress(handleIdentityKeyPress, {
    isActive: step === 'identity',
    priority: true,
  });

  // Handle Tab for "Back" and any key for success exit
  const handleGlobalKeys = useCallback((key: Key) => {
    if (step === 'success') {
      onComplete();
      return true;
    }
    if (key.name === 'tab' && !key.shift) {
      handleBack();
      return true;
    }
    return false;
  }, [step, handleBack, onComplete]);

  useKeypress(handleGlobalKeys, { isActive: true, priority: true });

  if (step === 'identity') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 1: Team Identity
        </Text>
        <Box marginTop={1} flexDirection="column">
          <Text color={theme.text.secondary}>Slug Name (e.g., coding-team):</Text>
          <TextInput
            buffer={nameBuffer}
            focus={activeIdentityField === 0}
            onSubmit={handleNext}
          />

          <Box marginTop={1} flexDirection="column">
            <Text color={theme.text.secondary}>Display Name (e.g., The Coding Team):</Text>
            <TextInput
              buffer={displayNameBuffer}
              focus={activeIdentityField === 1}
              onSubmit={handleNext}
            />
          </Box>

          <Box marginTop={1} flexDirection="column">
            <Text color={theme.text.secondary}>Short Description:</Text>
            <TextInput
              buffer={descBuffer}
              focus={activeIdentityField === 2}
              onSubmit={handleNext}
            />
          </Box>
        </Box>
        <DialogFooter
          primaryAction="Enter to continue"
          navigationActions="↑/↓ to switch fields"
          cancelAction="Esc to cancel"
        />
      </Box>
    );
  }

  if (step === 'objective') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 2: Team Objective
        </Text>
        <Box marginTop={1}>
          <Text color={theme.text.secondary}>
            Enter orchestration instructions. This guides the top-level agent on
            how to use this team effectively.
          </Text>
        </Box>
        <Box
          marginTop={1}
          borderStyle="single"
          borderColor={theme.ui.comment}
          paddingX={1}
        >
          <TextInput buffer={instructionsBuffer} onSubmit={handleNext} />
        </Box>
        <DialogFooter
          primaryAction="Enter to continue"
          navigationActions="Tab to go back"
        />
      </Box>
    );
  }

  if (step === 'roster') {
    const rosterItems = allAvailableAgents.map((a) => ({
      key: a.name,
      value: a,
    }));
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    rosterItems.push({ key: 'done', value: { name: 'done', kind: 'local' } as any });

    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 3: Team Roster
        </Text>
        <Box marginTop={1}>
          <Text color={theme.text.secondary}>
            Select agents to include in your team.
          </Text>
        </Box>
        <Box marginTop={1}>
          <BaseSelectionList
            items={rosterItems}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            onSelect={(item: any) => {
              if (item.value.name === 'done') handleNext();
              else handleToggleAgent(item.value.name);
            }}
            maxItemsToShow={10}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            renderItem={(item: any, context) => {
              if (item.value.name === 'done') {
                return (
                  <Text
                    bold
                    color={
                      context.isSelected ? theme.text.accent : theme.text.primary
                    }
                  >
                    [ Done - Continue to Confirmation ]
                  </Text>
                );
              }
              const isChecked = selectedAgents.has(item.value.name);
              const provider = 'provider' in item.value ? item.value.provider : undefined;
              return (
                <Box flexDirection="column">
                  <Box flexDirection="row">
                    <Text
                      color={
                        isChecked ? theme.status.success : theme.text.secondary
                      }
                    >
                      [{isChecked ? 'x' : ' '}]
                    </Text>
                    <Text
                      color={
                        context.isSelected
                          ? theme.text.accent
                          : theme.text.primary
                      }
                    >
                      {' '}
                      {item.value.name}
                    </Text>
                    <Text color={theme.text.secondary}>
                      {' '}
                      ({item.value.kind}
                      {provider ? `: ${String(provider)}` : ''})
                    </Text>
                  </Box>
                  {item.value.description && (
                    <Text color={theme.text.secondary} italic>
                      {'  '}{item.value.description}
                    </Text>
                  )}
                </Box>
              );
            }}
          />
        </Box>
        <DialogFooter
          primaryAction="Enter to toggle/confirm"
          navigationActions="Tab to go back"
        />
      </Box>
    );
  }

  if (step === 'confirmation') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 4: Confirm Team Creation
        </Text>
        <Box marginTop={1} flexDirection="column">
          <Text color={theme.text.secondary}>
            Name: <Text color={theme.text.primary}>{displayName} ({teamName})</Text>
          </Text>
          <Text color={theme.text.secondary}>
            Description: <Text color={theme.text.primary}>{description}</Text>
          </Text>
          <Box marginTop={1}>
            <Text color={theme.text.secondary}>
              Roster:
            </Text>
          </Box>
          {Array.from(selectedAgents).map((name) => (
            <Text key={name} color={theme.text.primary}>
              - {name}
            </Text>
          ))}
          {selectedAgents.size === 0 && (
            <Text color={theme.status.warning} italic>
              No agents selected (Gemini CLI expert will be used by default)
            </Text>
          )}
        </Box>

        {error && (
          <Box marginTop={1}>
            <Text color={theme.status.error}>Error: {error}</Text>
          </Box>
        )}

        <Box marginTop={1}>
          {isSubmitting ? (
            <Text color={theme.text.accent}>Creating team...</Text>
          ) : (
            <DialogFooter
              primaryAction="Enter to create team"
              navigationActions="Tab to go back"
              // @ts-expect-error onSelect exists in this branch of DialogFooter
              onSelect={handleCreate}
            />
          )}
        </Box>
      </Box>
    );
  }

  if (step === 'success') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.status.success}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.status.success}>
          Team Created Successfully!
        </Text>
        <Box marginTop={1}>
          <Text color={theme.text.primary}>
            Your new team &quot;{displayName}&quot; is now ready to use.
          </Text>
        </Box>
        <Box marginTop={1}>
          <Text color={theme.text.accent}>Press any key to return to selection...</Text>
        </Box>
      </Box>
    );
  }

  return <Box />;
}

