  '[18~': { name: 'f7' },
  '[19~': { name: 'f8' },
  '[20~': { name: 'f9' },
  '[21~': { name: 'f10' },
  '[23~': { name: 'f11' },
  '[24~': { name: 'f12' },
  '[25~': { name: 'f13' },
  '[26~': { name: 'f14' },
  '[28~': { name: 'f15' },
  '[29~': { name: 'f16' },
  '[31~': { name: 'f17' },
  '[32~': { name: 'f18' },
  '[33~': { name: 'f19' },
  '[34~': { name: 'f20' },
  '[A': { name: 'up' },
  '[B': { name: 'down' },
  '[C': { name: 'right' },
  '[D': { name: 'left' },
  '[E': { name: 'clear' },
  '[F': { name: 'end' },
  '[H': { name: 'home' },
