      key: 'create',
      titleSuffix: undefined,
    });

    return list;
  }, [discoveredTeams]);

  const handleSelect = useCallback(
    (value: string) => {
      if (value === 'none') {
        onSelect(undefined);
      } else if (value === 'marketplace') {
        setView('marketplace');
      } else if (value === 'create') {
        uiActions.setIsTeamCreatorActive(true);
        onSelect(undefined);
      } else {
        onSelect(value);
      }
    },
    [onSelect, uiActions],
  );

  if (view === 'marketplace') {
    return (
      <Box
        borderStyle="round"
        borderColor={theme.border.default}
        flexDirection="column"
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Agent Team Marketplace
        </Text>
        <Box marginTop={1} flexDirection="column">
          <Text color={theme.text.secondary}>
            Explore and download community-contributed agent teams.
          </Text>
          <Box
            marginTop={1}
            padding={1}
            borderStyle="single"
            borderColor={theme.ui.comment}
          >
            <Text color={theme.ui.comment}>
              The community marketplace is currently under development. Soon you
              will be able to browse hundreds of specialized teams.
            </Text>
          </Box>
          <Box marginTop={1}>
            <Text color={theme.text.accent}>
              Press any key to go back to selection...
            </Text>
          </Box>
        </Box>
      </Box>
    );
  }

  return (
    <Box
      borderStyle="round"
      borderColor={theme.border.default}
      flexDirection="column"
      padding={1}
      width="100%"
    >
      <Text bold color={theme.text.primary}>
        Select an Agent Team
      </Text>
      <Text color={theme.text.secondary}>
        Choose a specialized team to orchestrate your tasks.
      </Text>

      <Box marginTop={1}>
        <DescriptiveRadioButtonSelect
          items={options}
          onSelect={handleSelect}
          showNumbers={true}
          maxItemsToShow={10}
        />
      </Box>

      <Box marginTop={1}>
        <Text color={theme.text.secondary}>
          (Use arrow keys to navigate, Enter to select)
        </Text>
      </Box>
    </Box>
  );
}

