      name: 'create',
      description: 'Create a new agent team interactively',
      kind: CommandKind.BUILT_IN,
      autoExecute: true,
      action: async (): Promise<MessageActionReturn> => {
        return {
          type: 'message',
          messageType: 'info',
          content: 'Opening team creator...',
        };
      },
    },
  ],
};

