      const result = await setupProcessorHook({
        builtinCommands: [command],
      });
      await waitFor(() => expect(result.current.slashCommands).toHaveLength(1));

      let handled: Awaited<
        ReturnType<typeof result.current.handleSlashCommand>
      >;
      await act(async () => {
