import type React from 'react';
import { useState, useMemo, useCallback } from 'react';
import { Box, Text } from 'ink';
import {
  type ScaffoldTeamAgent,
  scaffoldTeam,
} from '@google/gemini-cli-core';
import { theme } from '../semantic-colors.js';
import { TextInput } from './shared/TextInput.js';
import { useTextBuffer } from './shared/text-buffer.js';
import { BaseSelectionList } from './shared/BaseSelectionList.js';
import { DialogFooter } from './shared/DialogFooter.js';
import { useConfig } from '../contexts/ConfigContext.js';
import { useKeypress, type Key } from '../hooks/useKeypress.js';
import { Command } from '../key/keyMatchers.js';
import { useKeyMatchers } from '../hooks/useKeyMatchers.js';
import { type SelectionListItem } from '../hooks/useSelectionList.js';

interface TeamCreatorWizardProps {
  onComplete: () => void;
  onCancel: () => void;
}

type WizardStep = 'identity' | 'objective' | 'roster' | 'confirmation' | 'success';

const EXTERNAL_TEMPLATES: ScaffoldTeamAgent[] = [
  {
    name: 'claude-coder',
    kind: 'external',
    provider: 'claude-code',
    description: 'Expert Claude coder focused on direct action.',
  },
  {
    name: 'codex-architect',
    kind: 'external',
    provider: 'codex',
    description: 'Specialized code generation and architectural patterns.',
  },
  {
    name: 'antigravity-creative',
    kind: 'external',
    provider: 'antigravity',
    description: 'Creative problem solving and unconventional solutions.',
  },
  {
    name: 'gemma-helper',
    kind: 'external',
    provider: 'gemma',
    description: 'Lightweight and efficient general purpose assistant.',
  },
];

interface RosterListItem {
  name: string;
  kind: 'local' | 'external' | 'meta';
  provider?: string;
  description?: string;
  sourcePath?: string;
}

export function TeamCreatorWizard({
  onComplete,
  onCancel,
}: TeamCreatorWizardProps): React.JSX.Element {
  const config = useConfig();
  const keyMatchers = useKeyMatchers();
  const [step, setStep] = useState<WizardStep>('identity');
  const [teamName, setTeamName] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [description, setDescription] = useState('');
  const [instructions, setInstructions] = useState('');
  const [selectedAgents, setSelectedAgents] = useState<Set<string>>(new Set());
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const localAgents = useMemo(
    () =>
      config
        ?.getAgentRegistry()
        .getAllDefinitions()
        .filter((a) => a.kind === 'local') || [],
    [config],
  );

  const allAvailableAgents = useMemo((): RosterListItem[] => {
    const local: RosterListItem[] = localAgents.map((a) => ({
      name: a.name,
      kind: 'local' as const,
      description: a.description,
      sourcePath: a.metadata?.filePath,
    }));
    const external: RosterListItem[] = EXTERNAL_TEMPLATES.map((a) => ({
      name: a.name,
      kind: 'external' as const,
      provider: a.provider,
      description: a.description,
    }));
    return [...local, ...external];
  }, [localAgents]);

  const handleNext = useCallback(() => {
    if (step === 'identity') setStep('objective');
    else if (step === 'objective') setStep('roster');
    else if (step === 'roster') setStep('confirmation');
  }, [step]);

  const handleBack = useCallback(() => {
    if (step === 'objective') setStep('identity');
    else if (step === 'roster') setStep('objective');
    else if (step === 'confirmation') setStep('roster');
    else if (step === 'identity') onCancel();
    else if (step === 'success') onComplete();
  }, [step, onCancel, onComplete]);

  const handleToggleAgent = (name: string) => {
    const next = new Set(selectedAgents);
    if (next.has(name)) next.delete(name);
    else next.add(name);
    setSelectedAgents(next);
  };

  const handleCreate = async () => {
    setIsSubmitting(true);
    setError(null);
    try {
      const agentsToScaffold: ScaffoldTeamAgent[] = allAvailableAgents
        .filter((a) => selectedAgents.has(a.name) && a.kind !== 'meta')
        .map((a) => ({
          name: a.name,
          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
          kind: a.kind as 'local' | 'external',
          provider: a.provider,
          description: a.description,
          sourcePath: a.sourcePath,
        }));
      await scaffoldTeam({
        name: teamName,
        displayName,
        description,
        instructions,
        agents: agentsToScaffold,
        targetDir: config.storage.getProjectTeamsDir(),
      });
      await config.getTeamRegistry().reload();
      setStep('success');
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setIsSubmitting(false);
    }
  };

  // Identity Step Buffers
  const nameBuffer = useTextBuffer({
    initialText: teamName,
    viewport: { width: 40, height: 1 },
    onChange: setTeamName,
    singleLine: true,
  });
  const displayNameBuffer = useTextBuffer({
    initialText: displayName,
    viewport: { width: 40, height: 1 },
    onChange: setDisplayName,
    singleLine: true,
  });
  const descBuffer = useTextBuffer({
    initialText: description,
    viewport: { width: 80, height: 1 },
    onChange: setDescription,
    singleLine: true,
  });

  // Objective Step Buffer
  const instructionsBuffer = useTextBuffer({
    initialText: instructions,
    viewport: { width: 80, height: 5 },
    onChange: setInstructions,
  });

  const [activeIdentityField, setActiveIdentityField] = useState<0 | 1 | 2>(0);

  const handleIdentityKeyPress = useCallback(
    (key: Key) => {
      if (keyMatchers[Command.DIALOG_NAVIGATION_DOWN](key)) {
        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        setActiveIdentityField(((activeIdentityField + 1) % 3) as 0 | 1 | 2);
        return true;
      }
      if (keyMatchers[Command.DIALOG_NAVIGATION_UP](key)) {
        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        setActiveIdentityField(((activeIdentityField + 2) % 3) as 0 | 1 | 2);
        return true;
      }
      if (keyMatchers[Command.ESCAPE](key)) {
        onCancel();
        return true;
      }
      return false;
    },
    [activeIdentityField, keyMatchers, onCancel],
  );

  useKeypress(handleIdentityKeyPress, {
    isActive: step === 'identity',
    priority: true,
  });

  // Handle Tab for "Back" and any key for success exit
  const handleGlobalKeys = useCallback((key: Key) => {
    if (step === 'success') {
      onComplete();
      return true;
    }
    if (key.name === 'tab' && !key.shift) {
      handleBack();
      return true;
    }
    return false;
  }, [step, handleBack, onComplete]);

  useKeypress(handleGlobalKeys, { isActive: true, priority: true });

  if (step === 'identity') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 1: Team Identity
        </Text>
        <Box marginTop={1} flexDirection="column">
          <Text color={theme.text.secondary}>Slug Name (e.g., coding-team):</Text>
          <TextInput
            buffer={nameBuffer}
            focus={activeIdentityField === 0}
            onSubmit={handleNext}
          />

          <Box marginTop={1} flexDirection="column">
            <Text color={theme.text.secondary}>Display Name (e.g., The Coding Team):</Text>
            <TextInput
              buffer={displayNameBuffer}
              focus={activeIdentityField === 1}
              onSubmit={handleNext}
            />
          </Box>

          <Box marginTop={1} flexDirection="column">
            <Text color={theme.text.secondary}>Short Description:</Text>
            <TextInput
              buffer={descBuffer}
              focus={activeIdentityField === 2}
              onSubmit={handleNext}
            />
          </Box>
        </Box>
        <DialogFooter
          primaryAction="Enter to continue"
          navigationActions="↑/↓ to switch fields"
          cancelAction="Esc to cancel"
        />
      </Box>
    );
  }

  if (step === 'objective') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 2: Team Objective
        </Text>
        <Box marginTop={1}>
          <Text color={theme.text.secondary}>
            Enter orchestration instructions. This guides the top-level agent on
            how to use this team effectively.
          </Text>
        </Box>
        <Box
          marginTop={1}
          borderStyle="single"
          borderColor={theme.ui.comment}
          paddingX={1}
        >
          <TextInput buffer={instructionsBuffer} onSubmit={handleNext} />
        </Box>
        <DialogFooter
          primaryAction="Enter to continue"
          navigationActions="Tab to go back"
        />
      </Box>
    );
  }

  if (step === 'roster') {
    const rosterItems: SelectionListItem<RosterListItem>[] = allAvailableAgents.map((a) => ({
      key: a.name,
      value: a,
    }));
    rosterItems.push({
      key: 'done',
      value: { name: 'done', kind: 'meta' as const },
    });

    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 3: Team Roster
        </Text>
        <Box marginTop={1}>
          <Text color={theme.text.secondary}>
            Select agents to include in your team.
          </Text>
        </Box>
        <Box marginTop={1}>
          <BaseSelectionList<RosterListItem>
            items={rosterItems}
            onSelect={(item) => {
              if (item.name === 'done') handleNext();
              else handleToggleAgent(item.name);
            }}
            maxItemsToShow={10}
            renderItem={(item, context) => {
              const value = item.value;
              if (value.name === 'done') {
                return (
                  <Text
                    bold
                    color={
                      context.isSelected ? theme.text.accent : theme.text.primary
                    }
                  >
                    [ Done - Continue to Confirmation ]
                  </Text>
                );
              }
              const isChecked = selectedAgents.has(value.name);
              return (
                <Box flexDirection="column">
                  <Box flexDirection="row">
                    <Text
                      color={
                        isChecked ? theme.status.success : theme.text.secondary
                      }
                    >
                      [{isChecked ? 'x' : ' '}]
                    </Text>
                    <Text
                      color={
                        context.isSelected
                          ? theme.text.accent
                          : theme.text.primary
                      }
                    >
                      {' '}
                      {value.name}
                    </Text>
                    {value.kind === 'external' ? (
                      <Text color={theme.text.accent} bold>
                        {' '}
                        [EXTERNAL]
                      </Text>
                    ) : !value.sourcePath ? (
                      <Text color={theme.ui.comment} italic>
                        {' '}
                        [BUILT-IN]
                      </Text>
                    ) : null}
                    <Text color={theme.text.secondary}>
                      {' '}
                      ({value.kind}
                      {value.provider ? `: ${value.provider}` : ''})
                    </Text>
                  </Box>
                  {value.description && (
                    <Text color={theme.text.secondary} italic>
                      {'  '}{value.description}
                    </Text>
                  )}
                </Box>
              );
            }}
          />
        </Box>
        <DialogFooter
          primaryAction="Enter to toggle/confirm"
          navigationActions="Tab to go back"
        />
      </Box>
    );
  }

  if (step === 'confirmation') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.border.default}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.text.primary}>
          Step 4: Confirm Team Creation
        </Text>
        <Box marginTop={1} flexDirection="column">
          <Text color={theme.text.secondary}>
            Name: <Text color={theme.text.primary}>{displayName} ({teamName})</Text>
          </Text>
          <Text color={theme.text.secondary}>
            Description: <Text color={theme.text.primary}>{description}</Text>
          </Text>
          <Box marginTop={1}>
            <Text color={theme.text.secondary}>
              Roster:
            </Text>
          </Box>
          {Array.from(selectedAgents).map((name) => (
            <Text key={name} color={theme.text.primary}>
              - {name}
            </Text>
          ))}
          {selectedAgents.size === 0 && (
            <Text color={theme.status.warning} italic>
              No agents selected (Gemini CLI expert will be used by default)
            </Text>
          )}
        </Box>

        {error && (
          <Box marginTop={1}>
            <Text color={theme.status.error}>Error: {error}</Text>
          </Box>
        )}

        <Box marginTop={1}>
          {isSubmitting ? (
            <Text color={theme.text.accent}>Creating team...</Text>
          ) : (
            <DialogFooter
              primaryAction="Enter to create team"
              navigationActions="Tab to go back"
              // @ts-expect-error onSelect exists in this branch of DialogFooter
              onSelect={handleCreate}
            />
          )}
        </Box>
      </Box>
    );
  }

  if (step === 'success') {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor={theme.status.success}
        padding={1}
        width="100%"
      >
        <Text bold color={theme.status.success}>
          Team Created Successfully!
        </Text>
        <Box marginTop={1}>
          <Text color={theme.text.primary}>
            Your new team &quot;{displayName}&quot; is now ready to use.
          </Text>
        </Box>
        <Box marginTop={1}>
          <Text color={theme.text.accent}>Press any key to return to selection...</Text>
        </Box>
      </Box>
    );
  }

  return <Box />;
}

