          </Box>
        </Box>

        {error && (
          <Box marginTop={1}>
            <Text color={theme.status.error}>Error: {error}</Text>
          </Box>
        )}

        <DialogFooter
          primaryAction="Enter to continue"
          navigationActions={`Tab to go back · ${formatCommand(Command.OPEN_EXTERNAL_EDITOR)} for full editor`}
          cancelAction="Esc to cancel"
