    logoColor: '#FFFFAF', // Yellow
  },
  {
    name: 'gemma-helper',
    kind: 'external',
    provider: 'gemma',
    description: 'Lightweight and efficient general purpose assistant.',
    logo: '󱜚',
    logoColor: '#87AFFF', // Blue
  },
];

interface RosterListItem {
