        includeDirectories: this.pendingIncludeDirectories,
        policyManager: this._sandboxPolicyManager,
      },
      initialApprovalMode,
    );

    if (
      !(this._sandboxManager instanceof NoopSandboxManager) &&
      this.sandbox.enabled
