                      )}
                      <Text color={theme.ui.comment}>@{name} </Text>
                      <ProviderTag provider={agent?.provider || 'gemini'} />
                      {i < selectedAgents.size - 1 && (
                        <Text color={theme.ui.comment}>, </Text>
                      )}
                    </Box>
                  );
                })}
              </Box>
